mapper.select:
SELECT EXISTS (
    SELECT 1
    FROM tb_customer_info
    WHERE customer_id = #{id, jdbcType=BIGINT}
      AND tenant_id = #{tenantId, jdbcType=BIGINT}
      AND use_at = 'Y'
)

SELECT EXISTS (
    SELECT 1
    FROM tb_material_info
    WHERE material_id = #{id, jdbcType=BIGINT}
      AND tenant_id = #{tenantId, jdbcType=BIGINT}
      AND delete_status = 'N'
      AND deleted_at IS NULL
)

SELECT h.sales_order_id AS salesOrderId, d.sales_order_detail_id AS salesOrderDetailId, pd.sales_delivery_plan_detail_id AS salesDeliveryPlanDetailId, h.order_no AS orderNo, h.order_dt AS orderDt, h.customer_id AS customerId, c.customer_code AS customerCode, c.customer_name AS customerName, ph.plan_no AS planNo, h.delivery_place AS deliveryPlace, h.delivery_method AS deliveryMethod, pd.line_no AS lineNo, pd.plan_dt AS planDt, d.material_id AS materialId, m.material_code AS materialCode, m.material_name AS materialName, m.unit AS unit, d.order_qty AS orderQty, COALESCE(d.shipped_qty, 0) AS shippedQty, pd.planned_qty AS plannedQty, pd.delivered_qty AS deliveredQty, pd.planned_qty - pd.delivered_qty AS remainingQty, d.unit_price AS unitPrice FROM tb_sales_order_hd h JOIN tb_sales_order_dt d ON d.sales_order_id = h.sales_order_id AND d.tenant_id = h.tenant_id JOIN tb_sales_delivery_plan_hd ph ON ph.sales_order_id = h.sales_order_id AND ph.tenant_id = h.tenant_id AND ph.use_at = 'Y' JOIN tb_sales_delivery_plan_dt pd ON pd.sales_delivery_plan_id = ph.sales_delivery_plan_id AND pd.sales_order_id = d.sales_order_id AND pd.sales_order_detail_id = d.sales_order_detail_id AND pd.tenant_id = d.tenant_id JOIN tb_customer_info c ON c.customer_id = h.customer_id AND c.tenant_id = h.tenant_id AND c.use_at = 'Y' JOIN tb_material_info m ON m.material_id = d.material_id AND m.tenant_id = d.tenant_id AND m.delete_status = 'N' AND m.deleted_at IS NULL WHERE h.tenant_id = #{tenantId, jdbcType=BIGINT} AND h.use_at = 'Y' AND h.status NOT IN ('수주취소', '취소', '출하완료', '완료') AND (pd.planned_qty > pd.delivered_qty OR EXISTS ( SELECT 1 FROM tb_tenant t WHERE t.tenant_id = h.tenant_id AND t.use_at = 'Y' AND t.over_delivery_policy = 'WARN' ))
AND (h.order_no ILIKE '%' || #{keyword} || '%' OR c.customer_code ILIKE '%' || #{keyword} || '%' OR c.customer_name ILIKE '%' || #{keyword} || '%')
ORDER BY h.order_dt DESC, h.sales_order_id DESC, pd.line_no LIMIT #{limit}

INSERT INTO tb_sales_delivery_hd (
    tenant_id, delivery_no, delivery_dt, delivery_type, customer_id, sales_order_id,
    delivery_place, delivery_method, total_amt, remark, created_by
) VALUES (
    #{tenantId, jdbcType=BIGINT}, #{deliveryNo}, CAST(#{deliveryDt} AS date),
    #{deliveryType, jdbcType=VARCHAR}, #{customerId, jdbcType=BIGINT},
    #{salesOrderId, jdbcType=BIGINT}, #{deliveryPlace}, #{deliveryMethod},
    #{totalAmt, jdbcType=NUMERIC}, #{remark}, #{createdBy}
)
RETURNING sales_delivery_id

mapper.update:
UPDATE tb_sales_order_dt
SET shipped_qty = COALESCE(shipped_qty, 0) + #{deltaQty, jdbcType=NUMERIC}
WHERE sales_order_detail_id = #{salesOrderDetailId, jdbcType=BIGINT}
  AND sales_order_id = #{salesOrderId, jdbcType=BIGINT}
  AND tenant_id = #{tenantId, jdbcType=BIGINT}
  AND COALESCE(shipped_qty, 0) + #{deltaQty, jdbcType=NUMERIC} >= 0
  AND (#{deltaQty, jdbcType=NUMERIC} <= 0
       OR COALESCE(shipped_qty, 0) + #{deltaQty, jdbcType=NUMERIC} <= order_qty
       OR EXISTS (
           SELECT 1 FROM tb_tenant t
           WHERE t.tenant_id = tb_sales_order_dt.tenant_id
             AND t.use_at = 'Y' AND t.over_delivery_policy = 'WARN'
       ))

mapper.delete:
DELETE FROM tb_sales_delivery_dt
WHERE sales_delivery_id = #{salesDeliveryId, jdbcType=BIGINT}
  AND tenant_id = #{tenantId, jdbcType=BIGINT}
